use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdecltrait! {
# [doc = " A `Sink` is a value into which other values can be sent, asynchronously."] # [doc = ""] # [doc = " Basic examples of sinks include the sending side of:"] # [doc = ""] # [doc = " - Channels"] # [doc = " - Sockets"] # [doc = " - Pipes"] # [doc = ""] # [doc = " In addition to such \"primitive\" sinks, it's typical to layer additional"] # [doc = " functionality, such as buffering, on top of an existing sink."] # [doc = ""] # [doc = " Sending to a sink is \"asynchronous\" in the sense that the value may not be"] # [doc = " sent in its entirety immediately. Instead, values are sent in a two-phase"] # [doc = " way: first by initiating a send, and then by polling for completion. This"] # [doc = " two-phase setup is analogous to buffered writing in synchronous code, where"] # [doc = " writes often succeed immediately, but internally are buffered and are"] # [doc = " *actually* written only upon flushing."] # [doc = ""] # [doc = " In addition, the `Sink` may be *full*, in which case it is not even possible"] # [doc = " to start the sending process."] # [doc = ""] # [doc = " As with `Future` and `Stream`, the `Sink` trait is built from a few core"] # [doc = " required methods, and a host of default methods for working in a"] # [doc = " higher-level way. The `Sink::send_all` combinator is of particular"] # [doc = " importance: you can use it to send an entire stream to a sink, which is"] # [doc = " the simplest way to ultimately consume a stream."] # [must_use = "sinks do nothing unless polled"] pub trait Sink < Item > { # [doc = " The type of value produced by the sink when an error occurs."] type Error ; # [doc = " Attempts to prepare the `Sink` to receive a value."] # [doc = ""] # [doc = " This method must be called and return `Poll::Ready(Ok(()))` prior to"] # [doc = " each call to `start_send`."] # [doc = ""] # [doc = " This method returns `Poll::Ready` once the underlying sink is ready to"] # [doc = " receive data. If this method returns `Poll::Pending`, the current task"] # [doc = " is registered to be notified (via `cx.waker().wake_by_ref()`) when `poll_ready`"] # [doc = " should be called again."] # [doc = ""] # [doc = " In most cases, if the sink encounters an error, the sink will"] # [doc = " permanently be unable to receive items."] fn poll_ready (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > ; # [doc = " Begin the process of sending a value to the sink."] # [doc = " Each call to this function must be preceded by a successful call to"] # [doc = " `poll_ready` which returned `Poll::Ready(Ok(()))`."] # [doc = ""] # [doc = " As the name suggests, this method only *begins* the process of sending"] # [doc = " the item. If the sink employs buffering, the item isn't fully processed"] # [doc = " until the buffer is fully flushed. Since sinks are designed to work with"] # [doc = " asynchronous I/O, the process of actually writing out the data to an"] # [doc = " underlying object takes place asynchronously. **You *must* use"] # [doc = " `poll_flush` or `poll_close` in order to guarantee completion of a"] # [doc = " send**."] # [doc = ""] # [doc = " Implementations of `poll_ready` and `start_send` will usually involve"] # [doc = " flushing behind the scenes in order to make room for new messages."] # [doc = " It is only necessary to call `poll_flush` if you need to guarantee that"] # [doc = " *all* of the items placed into the `Sink` have been sent."] # [doc = ""] # [doc = " In most cases, if the sink encounters an error, the sink will"] # [doc = " permanently be unable to receive items."] fn start_send (self : Pin < & mut Self > , item : Item) -> Result < () , Self :: Error > ; # [doc = " Flush any remaining output from this sink."] # [doc = ""] # [doc = " Returns `Poll::Ready(Ok(()))` when no buffered items remain. If this"] # [doc = " value is returned then it is guaranteed that all previous values sent"] # [doc = " via `start_send` have been flushed."] # [doc = ""] # [doc = " Returns `Poll::Pending` if there is more work left to do, in which"] # [doc = " case the current task is scheduled (via `cx.waker().wake_by_ref()`) to wake up when"] # [doc = " `poll_flush` should be called again."] # [doc = ""] # [doc = " In most cases, if the sink encounters an error, the sink will"] # [doc = " permanently be unable to receive items."] fn poll_flush (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > ; # [doc = " Flush any remaining output and close this sink, if necessary."] # [doc = ""] # [doc = " Returns `Poll::Ready(Ok(()))` when no buffered items remain and the sink"] # [doc = " has been successfully closed."] # [doc = ""] # [doc = " Returns `Poll::Pending` if there is more work left to do, in which"] # [doc = " case the current task is scheduled (via `cx.waker().wake_by_ref()`) to wake up when"] # [doc = " `poll_close` should be called again."] # [doc = ""] # [doc = " If this function encounters an error, the sink should be considered to"] # [doc = " have failed permanently, and no more `Sink` methods should be called."] fn poll_close (self : Pin < & mut Self > , cx : & mut Context < '_ >) -> Poll < Result < () , Self :: Error > > ; }
}